-- The hosted demo fund's 2026 books: bank feeds for Fund I and Fund II, the entries behind them,
-- quarter-end fee accruals and a June mark. Applied once to the demo fund on portfolio.hemrock.com
-- (fund e2dfd2bf…); `npm run demo:record` then captures what the pages show.
--
-- Bank rows follow the import model: reconciled rows carry a posted entry, drafted rows a draft,
-- unmatched rows none. The opening-balance rows carry the 2025-12-31 ledger cash so the bank
-- reconciliation's difference is exactly the open items. Every row is tagged
-- (journal_entries.source_ref = 'demo-seed-2026', bank_transactions.raw->>'demo_seed' = '2026');
-- demo-seed-2026-remove.sql takes it all out again.
begin;
select 'e2dfd2bf-ced3-4647-8277-096e616a6eab', v.g, v.vid, 'csv', 'demo-opening-2025-12-31', '2025-12-31', v.amt, 'Opening balance — statement ending 2025-12-31', 'First Republic Bank', 'reconciled', null, '1000',
  jsonb_build_object('date','2025-12-31','amount',v.amt,'description','Opening balance — statement ending 2025-12-31','counterparty','First Republic Bank','demo_seed','2026')
from (values ('Fund I','061ee98b-cea1-465e-a73c-d597df4afaba'::uuid,1055000.00),('Fund II','d73f3df5-5a2f-4c34-b431-e6c8d71fd4e9'::uuid,885000.00)) v(g,vid,amt);
commit;
